mapper.select:
SELECT id, name, location, capacity, equipment, status, remark, created_at, updated_at FROM meeting_room
AND (location LIKE CONCAT('%', #{location}, '%') OR name LIKE CONCAT('%', #{location}, '%'))
AND capacity >= #{minCapacity}
AND status = #{status}
ORDER BY id

SELECT room_id AS roomId, start_time AS startTime, end_time AS endTime FROM reservation WHERE reserve_date = #{date} AND status IN ('PENDING', 'ONGOING') AND room_id IN
#{roomId}
ORDER BY room_id, start_time
